/* TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Not part of the Unity framework: Tom's small fixture-macro layer (see README.md in this folder). */
#include "unity_fixture.h"

#include <stddef.h>

static UnityFixtureFunction g_setup = NULL;
static UnityFixtureFunction g_teardown = NULL;

/** Unity core calls this before every test; dispatch to the active group setup. */
void setUp(void)
{
    if (g_setup != NULL)
    {
        g_setup();
    }
}

/** Unity core calls this after every test; dispatch to the active group teardown. */
void tearDown(void)
{
    if (g_teardown != NULL)
    {
        g_teardown();
    }
}

/** Run one test while temporarily selecting its group setup/teardown hooks. */
void UnityFixture_RunTest(UnityTestFunction test,
                          const char *name,
                          int line,
                          UnityFixtureFunction setup,
                          UnityFixtureFunction teardown)
{
    g_setup = setup;
    g_teardown = teardown;
    UnityDefaultTestRun(test, name, line);
    g_setup = NULL;
    g_teardown = NULL;
}

/** Start Unity, run every registered group, and return Unity's final status. */
int UnityMain(int argc, const char *argv[], void (*run_all_tests)(void))
{
    (void)argc;
    (void)argv;

    if (run_all_tests == NULL)
    {
        return 1;
    }

    UnityBegin("PD5_AudioEffects");
    run_all_tests();
    return UnityEnd();
}
